<script setup>
import { ref, computed } from 'vue'
import { hasSavedSchedule } from './enrollment'
const props=defineProps({schedules:{type:Array,default:()=>[]}})
const view=ref('cards'),days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']
const scheduled=computed(()=>props.schedules.filter(hasSavedSchedule).sort((a,b)=>days.indexOf(a.day)-days.indexOf(b.day)||String(a.start_time).localeCompare(String(b.start_time))))
const unscheduled=computed(()=>props.schedules.filter(s=>!hasSavedSchedule(s)).sort((a,b)=>String(a.subject?.subject_code||'').localeCompare(String(b.subject?.subject_code||''))))
const ordered=computed(()=>[...scheduled.value,...unscheduled.value])
const print=()=>window.print()
</script>
<template><section class="en-schedule"><div class="en-actions en-no-print" aria-label="Schedule views"><button v-for="v in ['cards','timetable','list']" :key="v" :aria-pressed="view===v" @click="view=v">{{ v.charAt(0).toUpperCase()+v.slice(1) }}</button><button class="en-secondary" @click="print">Print schedule</button></div><p v-if="!schedules.length">No scheduled classes found.</p><div v-if="view==='cards'" class="en-grid"><article v-for="s in ordered" :key="s.id" class="en-card"><h3>{{ s.subject?.subject_code }}</h3><p>{{ s.subject?.subject_name }}</p><p>{{ hasSavedSchedule(s)?`${s.day} · ${s.start_time.slice(0,5)}–${s.end_time.slice(0,5)}`:'Day/time: -' }}</p><p>{{ hasSavedSchedule(s)?s.room:'Room: -' }} · {{ s.professor?.user?.profile?.first_name }} {{ s.professor?.user?.profile?.last_name }}</p><slot name="actions" :schedule="s"/></article></div><div v-else-if="view==='timetable'" class="en-timetable"><section v-for="day in days" :key="day"><h3>{{ day }}</h3><article v-for="s in scheduled.filter(s=>s.day===day)" :key="s.id" class="en-time-class"><strong>{{ s.start_time.slice(0,5) }}–{{ s.end_time.slice(0,5) }}</strong><p>{{ s.subject?.subject_code }} · {{ s.room }}</p><slot name="actions" :schedule="s"/></article></section><section v-if="unscheduled.length"><h3>Unscheduled</h3><article v-for="s in unscheduled" :key="s.id" class="en-time-class"><strong>Day/time: -</strong><p>{{ s.subject?.subject_code }} · Room: -</p><slot name="actions" :schedule="s"/></article></section></div><div v-else class="en-table"><table><thead><tr><th>Subject</th><th>Day / time</th><th>Room / Professor</th><th class="en-no-print">Actions</th></tr></thead><tbody><tr v-for="s in ordered" :key="s.id"><td>{{ s.subject?.subject_code }} {{ s.subject?.subject_name }}</td><td>{{ hasSavedSchedule(s)?`${s.day} ${s.start_time.slice(0,5)}–${s.end_time.slice(0,5)}`:'-' }}</td><td>{{ hasSavedSchedule(s)?s.room:'-' }} · {{ s.professor?.user?.profile?.first_name }} {{ s.professor?.user?.profile?.last_name }}</td><td class="en-no-print"><slot name="actions" :schedule="s"/></td></tr></tbody></table></div></section></template>
